  text-shadow: 0 0 var(--fsv-blur) var(--fsv-glow-color);
}

@keyframes glow-breathe {
  0%,
  100% {
    text-shadow:
      0 0 15px var(--fsv-glow-color),
      0 0 30px var(--fsv-glow-color);
    opacity: 0.95;
  }

  50% {
    text-shadow:
      0 0 25px var(--fsv-glow-color),
      0 0 50px var(--fsv-glow-color),
      0 0 80px var(--fsv-glow-color);
    opacity: 1;
  }
